practiceProblems.solutionCode:
public class Main {
    public static void main(String[] args) {
        int i = 1;
        while (i <= 3) {
            System.out.println(i);
            i++;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        for (int i = 5; i >= 3; i--) {
            System.out.println(i);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int step = 0;
        while (true) {
            step++;
            System.out.println("Step: " + step);
            if (step == 4) {
                break;
            }
        }
        System.out.println("Safety limit reached.");
    }
}

public class Main {
    public static void main(String[] args) {
        int n = 1;
        while (n <= 3) {
            System.out.println("Pass: " + n);
            n++;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int[] arr = {10, 20, 30};
        for (int i = 0; i < arr.length; i++) {
            System.out.println("Item " + i + ": " + arr[i]);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        for (int i = 1; i <= 3; i++) {
            System.out.printf("%.1f%n", i / 10.0);
        }
    }
}
